use serde::Deserialize;
use serde::Serialize;
use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::net::TcpStream;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::thread;
use std::time::Instant;

const DEFAULT_DATA_DIR: &str = "/opt/vdb-data";

#[derive(Deserialize)]
struct QueryVector {
    vector: Vec<f32>,
}

#[derive(Serialize)]
struct SearchRequest<'a> {
    vector: &'a [f32],
    top_k: u32,
}

struct Args {
    server_url: String,
    data_dir: PathBuf,
    queries: usize,
    warmup: usize,
    concurrency: usize,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = parse_args()?;
    let bodies = load_bodies(&args.data_dir)?;
    let warmup_count = args.warmup.min(bodies.len());
    let measured_count = args.queries.min(bodies.len().saturating_sub(warmup_count));

    let warmup = &bodies[..warmup_count];
    let measured = &bodies[warmup_count..warmup_count + measured_count];

    if !warmup.is_empty() {
        let _ = replay_requests(&args.server_url, warmup, args.concurrency)?;
    }

    let duration_secs = replay_requests(&args.server_url, measured, args.concurrency)?;
    let qps = if duration_secs > 0.0 {
        measured_count as f64 / duration_secs
    } else {
        0.0
    };

    let payload = serde_json::json!({
        "type": "ReplaySearchBodiesFast",
        "server_url": args.server_url,
        "data_dir": args.data_dir,
        "warmup": warmup_count,
        "total_queries": measured_count,
        "concurrency": args.concurrency,
        "duration_secs": duration_secs,
        "qps": qps,
    });
    println!("{}", serde_json::to_string_pretty(&payload)?);
    Ok(())
}

fn parse_args() -> Result<Args, Box<dyn std::error::Error>> {
    let mut server_url = String::from("http://127.0.0.1:8080");
    let mut data_dir = PathBuf::from(env::var("VDB_DATA_DIR").unwrap_or_else(|_| DEFAULT_DATA_DIR.to_string()));
    let mut queries = 1000usize;
    let mut warmup = 100usize;
    let mut concurrency = 4usize;

    let mut iter = env::args().skip(1);
    while let Some(arg) = iter.next() {
        let value = match arg.as_str() {
            "--server-url" | "--data-dir" | "--queries" | "--warmup" | "--concurrency" => {
                iter.next().ok_or_else(|| format!("missing value for {arg}"))?
            }
            "--help" | "-h" => {
                print_help();
                std::process::exit(0);
            }
            other => return Err(format!("unknown argument: {other}").into()),
        };

        match arg.as_str() {
            "--server-url" => server_url = value,
            "--data-dir" => data_dir = PathBuf::from(value),
            "--queries" => queries = value.parse()?,
            "--warmup" => warmup = value.parse()?,
            "--concurrency" => concurrency = value.parse()?,
            _ => unreachable!(),
        }
    }

    Ok(Args {
        server_url,
        data_dir,
        queries,
        warmup,
        concurrency,
    })
}

fn print_help() {
    eprintln!("Usage: replay_search_bodies_fast [--server-url URL] [--data-dir DIR] [--queries N] [--warmup N] [--concurrency N]");
}

fn load_bodies(data_dir: &Path) -> Result<Vec<Vec<u8>>, Box<dyn std::error::Error>> {
    let query_path = data_dir.join("query_vectors.json");
    let query_bytes = fs::read(&query_path)?;
    let queries: Vec<QueryVector> = serde_json::from_slice(&query_bytes)?;
    let mut bodies = Vec::with_capacity(queries.len());

    for query in &queries {
        let body = serde_json::to_vec(&SearchRequest {
            vector: &query.vector,
            top_k: 10,
        })?;
        bodies.push(body);
    }

    Ok(bodies)
}

fn replay_requests(
    server_url: &str,
    bodies: &[Vec<u8>],
    concurrency: usize,
) -> Result<f64, Box<dyn std::error::Error>> {
    let (host, port, host_header) = parse_server_url(server_url)?;
    let requests: Arc<Vec<Vec<u8>>> = Arc::new(
        bodies
            .iter()
            .map(|body| build_http_request(&host_header, body))
            .collect(),
    );

    let worker_count = concurrency.max(1);
    let mut partitions = vec![Vec::new(); worker_count];
    for (idx, request_idx) in (0..requests.len()).enumerate() {
        partitions[idx % worker_count].push(request_idx);
    }

    let start = Instant::now();
    let mut handles = Vec::with_capacity(worker_count);
    for request_indexes in partitions {
        let requests = Arc::clone(&requests);
        let host = host.clone();
        handles.push(thread::spawn(move || run_worker(&host, port, &requests, &request_indexes)));
    }

    for handle in handles {
        handle.join().map_err(|_| "worker thread panicked")??;
    }

    Ok(start.elapsed().as_secs_f64())
}

fn parse_server_url(server_url: &str) -> Result<(String, u16, String), Box<dyn std::error::Error>> {
    let rest = server_url
        .strip_prefix("http://")
        .ok_or_else(|| format!("only plain http:// is supported, got: {server_url}"))?;
    let authority = rest.split('/').next().unwrap_or(rest);
    let mut parts = authority.splitn(2, ':');
    let host = parts.next().unwrap_or("127.0.0.1").to_string();
    let port = parts
        .next()
        .map(str::parse)
        .transpose()?
        .unwrap_or(80u16);
    Ok((host, port, authority.to_string()))
}

fn build_http_request(host_header: &str, body: &[u8]) -> Vec<u8> {
    let headers = format!(
        "POST /search HTTP/1.1\r\ncontent-type: application/json\r\naccept: */*\r\nhost: {host_header}\r\ncontent-length: {}\r\n\r\n",
        body.len()
    );

    let mut request = Vec::with_capacity(headers.len() + body.len());
    request.extend_from_slice(headers.as_bytes());
    request.extend_from_slice(body);
    request
}

fn run_worker(
    host: &str,
    port: u16,
    requests: &[Vec<u8>],
    request_indexes: &[usize],
) -> io::Result<()> {
    let mut stream = TcpStream::connect((host, port))?;
    stream.set_nodelay(true)?;
    let mut buffer = Vec::with_capacity(64 * 1024);

    for &request_idx in request_indexes {
        stream.write_all(&requests[request_idx])?;
        read_response(&mut stream, &mut buffer)?;
    }

    Ok(())
}

fn read_response(stream: &mut TcpStream, buffer: &mut Vec<u8>) -> io::Result<()> {
    loop {
        if let Some(header_end) = find_header_end(buffer) {
            let body_start = header_end + 4;
            let content_length =
                parse_content_length(&buffer[..header_end]).ok_or_else(bad_response_error)?;
            let body_end = body_start
                .checked_add(content_length)
                .ok_or_else(bad_response_error)?;

            if buffer.len() >= body_end {
                consume_buffer(buffer, body_end);
                return Ok(());
            }
        }

        let mut chunk = [0u8; 64 * 1024];
        let read = stream.read(&mut chunk)?;
        if read == 0 {
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "connection closed while waiting for response",
            ));
        }
        buffer.extend_from_slice(&chunk[..read]);
    }
}

fn find_header_end(buffer: &[u8]) -> Option<usize> {
    buffer.windows(4).position(|window| window == b"\r\n\r\n")
}

fn parse_content_length(header_block: &[u8]) -> Option<usize> {
    for line in header_block.split(|&byte| byte == b'\n') {
        let line = line.strip_suffix(b"\r").unwrap_or(line);
        let Some(colon) = line.iter().position(|&byte| byte == b':') else {
            continue;
        };
        let (name, value) = line.split_at(colon);
        if name.eq_ignore_ascii_case(b"content-length") {
            return std::str::from_utf8(value)
                .ok()?
                .trim_start_matches(':')
                .trim()
                .parse()
                .ok();
        }
    }
    None
}

fn consume_buffer(buffer: &mut Vec<u8>, consumed: usize) {
    if consumed >= buffer.len() {
        buffer.clear();
        return;
    }

    buffer.copy_within(consumed.., 0);
    buffer.truncate(buffer.len() - consumed);
}

fn bad_response_error() -> io::Error {
    io::Error::new(io::ErrorKind::InvalidData, "invalid HTTP response")
}

[package]
name = "vector-db-benchmark"
edition = "2021"

[dependencies]
tokio = { version = "1", features = ["full"] }
reqwest = { version = "0.12", features = ["json"] }
serde = { version = "1", features = ["derive"] }
serde_json = "1"
rand = "0.8"
clap = { version = "4", features = ["derive"] }

use clap::Parser;
use std::time::Instant;

mod anti_cheat;
mod loader;
mod runner;
mod scorer;

#[derive(Parser)]
#[command(name = "vector-db-benchmark")]
#[command(about = "Benchmark client for Vector DB evaluation")]
struct Cli {
    /// Server URL
    #[arg(long, default_value = "http://127.0.0.1:8080")]
    server_url: String,

    /// Number of concurrent query threads
    #[arg(long, default_value_t = 4)]
    concurrency: usize,

    /// Number of warmup queries
    #[arg(long, default_value_t = 1000)]
    warmup: usize,

    /// Path to base vectors JSON file
    #[arg(long)]
    base_vectors: String,

    /// Path to query vectors JSON file
    #[arg(long)]
    query_vectors: String,

    /// Path to ground truth JSON file
    #[arg(long)]
    ground_truth: String,

    /// Recall threshold (0.0 to 1.0)
    #[arg(long, default_value_t = 0.95)]
    recall_threshold: f64,

    /// Random seed for query shuffling
    #[arg(long, default_value_t = 42)]
    seed: u64,

    /// Batch size for bulk insert
    #[arg(long, default_value_t = 1000)]
    batch_size: usize,

    /// Maximum number of queries to run (0 = all)
    #[arg(long, default_value_t = 0)]
    max_queries: usize,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let cli = Cli::parse();
    let client = reqwest::Client::new();

    // 1. Load and insert base vectors
    eprintln!("Loading base vectors from {}...", cli.base_vectors);
    let base_vectors = loader::load_vectors_from_file(&cli.base_vectors).await?;
    eprintln!("Loaded {} base vectors, inserting...", base_vectors.len());
    let inserted = loader::bulk_insert_vectors(&client, &cli.server_url, &base_vectors, cli.batch_size).await?;
    eprintln!("Inserted {} vectors", inserted);

    // 2. Load query vectors and ground truth
    eprintln!("Loading query vectors from {}...", cli.query_vectors);
    let all_query_vectors = loader::load_vectors_from_file(&cli.query_vectors).await?;
    eprintln!("Loading ground truth from {}...", cli.ground_truth);
    let all_ground_truth = scorer::load_ground_truth(&cli.ground_truth).await?;

    // Apply max_queries limit if set
    let (query_vectors, ground_truth) = if cli.max_queries > 0 && cli.max_queries < all_query_vectors.len() {
        eprintln!("Limiting to {} queries (out of {})", cli.max_queries, all_query_vectors.len());
        let qv: Vec<_> = all_query_vectors.into_iter().take(cli.max_queries).collect();
        let gt: Vec<_> = all_ground_truth.into_iter().take(cli.max_queries).collect();
        (qv, gt)
    } else {
        (all_query_vectors, all_ground_truth)
    };

    // 3. Warmup
    eprintln!("Running {} warmup queries...", cli.warmup);
    runner::run_warmup(&client, &cli.server_url, &query_vectors, cli.warmup).await;

    // 4. Run benchmark queries
    eprintln!(
        "Running {} queries with concurrency {}...",
        query_vectors.len(),
        cli.concurrency
    );
    let start = Instant::now();
    let query_results = runner::run_queries(
        &client,
        &cli.server_url,
        &query_vectors,
        cli.concurrency,
        cli.seed,
    )
    .await;
    let duration_secs = start.elapsed().as_secs_f64();

    // 5. Compute results
    let result = scorer::compute_benchmark_result(
        &query_results,
        &ground_truth,
        duration_secs,
        cli.concurrency,
        cli.recall_threshold,
    );

    // 6. Anti-cheat detection
    let result_ids: Vec<Vec<u64>> = query_results
        .iter()
        .map(|qr| qr.results.iter().map(|r| r.id).collect())
        .collect();
    let anti_cheat = anti_cheat::detect_hardcoded_results(&result_ids);
    eprintln!("Anti-cheat: {}", anti_cheat.message);

    // 7. Output JSON to stdout
    let output = serde_json::json!({
        "benchmark": result,
        "anti_cheat": anti_cheat,
    });
    let json = serde_json::to_string_pretty(&output)?;
    println!("{}", json);

    Ok(())
}

